const prepare = function ({ result }) {
  if (!result || typeof result !== "object" || Array.isArray(result) || result.success !== true) {
    throw new Error("Firecrawl did not report a successful scrape.");
  }
  const response = result.data?.markdown;
  if (typeof response !== "string" || !response.trim()) {
    throw new Error("Firecrawl did not return nonempty Markdown.");
  }
  const status = result.data?.metadata?.statusCode;
  return {
    response,
    pageStatus: Number.isInteger(status) && status >= 100 && status <= 599 ? status : null,
  };
};

return $input
  .all()
  .map((item, index) => ({ json: prepare({ result: item.json }), pairedItem: { item: index } }));

const prepare = function ({ url }) {
  if (typeof url !== "string" || !/^https?:\/\/[^\s/]+(?:\/[^\s]*)?$/i.test(url.trim())) {
    throw new Error("Supply one nonempty HTTP or HTTPS page URL.");
  }
  return { url: url.trim() };
};

return $input
  .all()
  .map((item, index) => ({ json: prepare(item.json), pairedItem: { item: index } }));
